55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
75	
76	const itemsGroupedByType = (items: Item[]): Item[][] => {
77	  const byType = new Map<string, Item[]>();
78	  for (const item of items) {
79	    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
80	  }
81	  return [...byType.values()];
82	};
83	
84	const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;
85	
86	const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
87	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  itemsGroupedByType(items).reduce(
91	    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
92	    0,
93	  );
94	
95	const withFirstInsuranceSurcharge = (policyBase: number): number =>
96	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
97	
98	const roundPremiumInMHPCOsFavor = Math.ceil;
99	
100	const HIGH_ENCHANTMENT_THRESHOLD = 5;
101	
102	const isCursed = (item: Item): boolean => item.cursed === true;
103	
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	interface RiskSurcharge {
108	  appliesTo: (item: Item) => boolean;
109	  rateOfBasePremium: number;
110	}
111	
112	const RISK_SURCHARGES: RiskSurcharge[] = [
113	  { appliesTo: isCursed, rateOfBasePremium: 0.5 },
114	  { appliesTo: isHighlyEnchanted, rateOfBasePremium: 0.3 },
115	];
116	
117	const itemSurcharges = (item: Item): number =>
118	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
119	    (sum, surcharge) => sum + itemBasePremium(item) * surcharge.rateOfBasePremium,
120	    0,
121	  );
122	
123	const totalItemSurcharges = (items: Item[]): number =>
124	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
125	
126	const LOYALTY_DISCOUNT = 0.2;
127	const LOYALTY_THRESHOLD_YEARS = 2;
128	
129	const isLoyal = (customer: Customer): boolean =>
130	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
131	
132	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
133	  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT : 0;
134	
135	const premiumBeforeFee = (items: Item[], customer: Customer): number => {
136	  const policyBase = policyBasePremium(items);
137	  return (
138	    withFirstInsuranceSurcharge(policyBase) +
139	    totalItemSurcharges(items) -
140	    loyaltyDiscount(policyBase, customer)
141	  );
142	};
143	
144	const quotePremium = (items: Item[], customer: Customer): number =>
145	  roundPremiumInMHPCOsFavor(premiumBeforeFee(items, customer) + PROCESSING_FEE);
146	
147	const runStep = (step: Step, customer: Customer): StepResult => {
148	  if (step.op === "quote") {
149	    return { premium: quotePremium(step.items, customer) };
150	  }
151	  throw new Error(`Unsupported step: ${step.op}`);
152	};
153	
154	export const runScenario = (scenario: Scenario): ScenarioResult => ({
155	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
156	});
